        PoolKey key;
        bytes hookData;
    }

    IPoolManager public immutable poolManager = IPoolManager(V4Deployments8453.POOL_MANAGER);
    IV4Quoter public immutable v4Quoter = IV4Quoter(V4Deployments8453.QUOTER);

